static bool z_t85_startsWith(const z_t85_t* self, const z_t85_t* prefix);
static bool z_t85_startsWith(const z_t85_t* self, const z_t85_t* prefix) {
    if (prefix->size > self->size) return false;
    if (prefix->size == 0) return true;
    return memcmp(self->data, prefix->data, prefix->size) == 0;
}

static bool z_t85_endsWith(const z_t85_t* self, const z_t85_t* suffix);
static bool z_t85_endsWith(const z_t85_t* self, const z_t85_t* suffix) {
    if (suffix->size > self->size) return false;
    if (suffix->size == 0) return true;
    return memcmp(self->data + (self->size - suffix->size),
                  suffix->data, suffix->size) == 0;
}

static uint64_t z_t85_indexOf_raw(const z_t85_t* self, const z_t85_t* needle);
static uint64_t z_t85_indexOf_raw(const z_t85_t* self, const z_t85_t* needle) {
    if (needle->size == 0) return 0;
    if (needle->size > self->size) return UINT64_MAX;
    uint64_t last = self->size - needle->size;
    for (uint64_t i = 0; i <= last; i++) {
        if (memcmp(self->data + i, needle->data, needle->size) == 0) {
            return i;
        }
    }
    return UINT64_MAX;
}


static bool z_t85_contains(const z_t85_t* self, const z_t85_t* needle);
static bool z_t85_contains(const z_t85_t* self, const z_t85_t* needle) {
    return z_t85_indexOf_raw(self, needle) != UINT64_MAX;
}

static bool z_ascii_is_ws(unsigned char c);
static bool z_ascii_is_ws(unsigned char c) {
    return c == ' ' || c == '\t' || c == '\n'
        || c == '\v' || c == '\f' || c == '\r';
}

static z_t85_t z_t85_substring(const z_t85_t* self, uint64_t from, uint64_t to);
static z_t85_t z_t85_substring(const z_t85_t* self, uint64_t from, uint64_t to) {
    if (from > self->size || to > self->size || from > to) z_panic("substring: bounds error");
    return (z_t85_t){ .size = to - from, .data = self->data + from };
}
static uint64_t z_t85_hash(const z_t85_t* self);
static uint64_t z_t85_hash(const z_t85_t* self) {
    return z_siphash_stringview(*self);
}
static z_t85_t z_t85_trim(const z_t85_t* self);
static z_t85_t z_t85_trim(const z_t85_t* self) {
    const char* p = self->data;
    const char* end = self->data + self->size;
    while (p < end && z_ascii_is_ws((unsigned char)*p)) p++;
    while (end > p && z_ascii_is_ws((unsigned char)end[-1])) end--;
    z_t85_t out = { .size = (uint64_t)(end - p), .data = p };
    return out;
}

static z_t57_t z_t85_replace_impl(
    const z_t85_t* self, const z_t85_t* needle,
    const z_t85_t* repl, bool once);
static z_t57_t z_t85_replace_impl(
    const z_t85_t* self, const z_t85_t* needle,
    const z_t85_t* repl, bool once) {
    /* empty needle: just copy self */
    if (needle->size == 0) {
        z_t57_t z = {0};
        z.size = self->size;
        z.capacity = self->size + 1;
        z.data = (char*)z_xmalloc(z.capacity + 1);
        memcpy(z.data, self->data, self->size);
        z.data[self->size] = '\0';
        return z;
    }
    /* pass 1: count matches so we can size the output once */
    uint64_t matches = 0;
    if (needle->size <= self->size) {
        uint64_t last = self->size - needle->size;
        uint64_t i = 0;
        while (i <= last) {
            if (memcmp(self->data + i, needle->data, needle->size) == 0) {
                matches++;
                i += needle->size;
                if (once) break;
            } else {
                i++;
            }
        }
    }
    uint64_t delta_per =
        (repl->size > needle->size)
            ? (repl->size - needle->size)
            : 0;
    uint64_t shrink_per =
        (needle->size > repl->size)
            ? (needle->size - repl->size)
            : 0;
    uint64_t out_len = self->size + matches * delta_per - matches * shrink_per;
    z_t57_t z = {0};
    z.size = out_len;
    z.capacity = out_len + 1;
    z.data = (char*)z_xmalloc(z.capacity + 1);
    /* pass 2: copy with replacement */
    uint64_t src_i = 0, dst_i = 0, done_matches = 0;
    while (src_i < self->size) {
        bool can_match = (done_matches < matches)
                      && (src_i + needle->size <= self->size)
                      && (memcmp(self->data + src_i, needle->data, needle->size) == 0);
        if (can_match) {
            memcpy(z.data + dst_i, repl->data, repl->size);
            dst_i += repl->size;
            src_i += needle->size;
            done_matches++;
        } else {
            z.data[dst_i++] = self->data[src_i++];
        }
    }
    z.data[dst_i] = '\0';
    return z;
}

static z_t57_t z_t85_replace(
    const z_t85_t* self, const z_t85_t* needle,
    const z_t85_t* replacement);
static z_t57_t z_t85_replace(
    const z_t85_t* self, const z_t85_t* needle,
    const z_t85_t* replacement) {
    return z_t85_replace_impl(self, needle, replacement, false);
}

static z_t57_t z_t85_concat(
    const z_t85_t* self, const z_t85_t* other);
static z_t57_t z_t85_concat(
    const z_t85_t* self, const z_t85_t* other) {
    z_t57_t z = {0};
    uint64_t total = self->size + other->size;
    z.size = total;
    z.capacity = total + 1;
    z.data = (char*)z_xmalloc(z.capacity + 1);
    memcpy(z.data, self->data, self->size);
    memcpy(z.data + self->size, other->data, other->size);
    z.data[total] = '\0';
    return z;
}

static uint32_t z_utf8_decode_one(
    const char* data, uint64_t length, uint64_t* i);
static uint32_t z_utf8_decode_one(
    const char* data, uint64_t length, uint64_t* i) {
    uint64_t idx = *i;
    unsigned char b0 = (unsigned char)data[idx];
    if (b0 < 0x80) { *i = idx + 1; return (uint32_t)b0; }
    uint32_t cp;
    uint64_t need;
    if ((b0 & 0xE0) == 0xC0) { cp = b0 & 0x1Fu; need = 1; }
    else if ((b0 & 0xF0) == 0xE0) { cp = b0 & 0x0Fu; need = 2; }
    else if ((b0 & 0xF8) == 0xF0) { cp = b0 & 0x07u; need = 3; }
    else { *i = idx + 1; return 0xFFFDu; }
    if (idx + 1 + need > length) { *i = idx + 1; return 0xFFFDu; }
    for (uint64_t k = 1; k <= need; k++) {
        unsigned char b = (unsigned char)data[idx + k];
        if ((b & 0xC0) != 0x80) { *i = idx + 1; return 0xFFFDu; }
        cp = (cp << 6) | (b & 0x3Fu);
    }
    *i = idx + 1 + need;
    return cp;
}

static uint64_t z_t85_count(const z_t85_t* self);
static uint64_t z_t85_count(const z_t85_t* self) {
    uint64_t i = 0, n = 0;
    while (i < self->size) {
        (void)z_utf8_decode_one(self->data, self->size, &i);
        n++;
    }
    return n;
}

static z_t1534_t z_t85_indexOf(const z_t85_t* self, const z_t85_t* needle);
static z_t1534_t z_t85_indexOf(const z_t85_t* self, const z_t85_t* needle) {
    z_t1534_t out = {0};
    uint64_t r = z_t85_indexOf_raw(self, needle);
    if (r == UINT64_MAX) {
        out.tag = Z_OPTIONVAL_U64_TAG_NONE;
        return out;
    }
    out.tag = Z_OPTIONVAL_U64_TAG_SOME;
    out.data.some = r;
    return out;
}


static z_t1534_t z_t85_lastIndexOf(const z_t85_t* self, const z_t85_t* needle);
static z_t1534_t z_t85_lastIndexOf(const z_t85_t* self, const z_t85_t* needle) {
    z_t1534_t out = {0};
    if (needle->size == 0) {
        out.tag = Z_OPTIONVAL_U64_TAG_SOME;
        out.data.some = self->size;
        return out;
    }
    if (needle->size > self->size) {
        out.tag = Z_OPTIONVAL_U64_TAG_NONE;
        return out;
    }
    for (uint64_t i = self->size - needle->size + 1; i > 0; i--) {
        uint64_t idx = i - 1;
        if (memcmp(self->data + idx, needle->data, needle->size) == 0) {
            out.tag = Z_OPTIONVAL_U64_TAG_SOME;
            out.data.some = idx;
            return out;
        }
    }
    out.tag = Z_OPTIONVAL_U64_TAG_NONE;
    return out;
}


static z_t1297_t z_t85_byteAt(const z_t85_t* self, uint64_t i);
static z_t1297_t z_t85_byteAt(const z_t85_t* self, uint64_t i) {
    z_t1297_t out = {0};
    if (i >= self->size) {
        out.tag = Z_OPTIONVAL_U8_TAG_NONE;
        return out;
    }
    out.tag = Z_OPTIONVAL_U8_TAG_SOME;
    out.data.some = (uint8_t)self->data[i];
    return out;
}


static z_t6604_t z_t85_stripPrefix(
    const z_t85_t* self, const z_t85_t* p);
static z_t6604_t z_t85_stripPrefix(
    const z_t85_t* self, const z_t85_t* p) {
    z_t6604_t out = {0};
    if (p->size > self->size
        || (p->size > 0 && memcmp(self->data, p->data, p->size) != 0)) {
        out.tag = Z_OPTION_STRINGVIEW_TAG_NONE;
        return out;
    }
    z_t85_t* boxed = (z_t85_t*)z_xmalloc(sizeof(z_t85_t));
    boxed->data = self->data + p->size;
    boxed->size = self->size - p->size;
    out.tag = Z_OPTION_STRINGVIEW_TAG_SOME;
    out.data = boxed;
    return out;
}


static z_t7378_t z_t85_parseU64(const z_t85_t* self);
static z_t7378_t z_t85_parseU64(const z_t85_t* self) {
    z_t7378_t out = {0};
    if (self->size == 0) {
        out.tag = Z_RESULTVAL_U64_PARSEERROR_TAG_ERR;
        out.data.err = Z_PARSEERROR_TAG_EMPTY;
        return out;
    }
    uint64_t acc = 0;
    for (uint64_t i = 0; i < self->size; i++) {
        unsigned char c = (unsigned char)self->data[i];
        if (c < '0' || c > '9') {
            out.tag = Z_RESULTVAL_U64_PARSEERROR_TAG_ERR;
            out.data.err = Z_PARSEERROR_TAG_INVALIDDIGIT;
            return out;
        }
        uint64_t d = (uint64_t)(c - '0');
        if (acc > (UINT64_MAX - d) / 10) {
            out.tag = Z_RESULTVAL_U64_PARSEERROR_TAG_ERR;
            out.data.err = Z_PARSEERROR_TAG_OVERFLOW;
            return out;
        }
        acc = acc * 10 + d;
    }
    out.tag = Z_RESULTVAL_U64_PARSEERROR_TAG_OK;
    out.data.ok = acc;
    return out;
}


static z_t7201_t z_t85_parseF64(const z_t85_t* self);
static z_t7201_t z_t85_parseF64(const z_t85_t* self) {
    z_t7201_t out = {0};
    if (self->size == 0) {
        out.tag = Z_RESULTVAL_F64_PARSEERROR_TAG_ERR;
        out.data.err = Z_PARSEERROR_TAG_EMPTY;
        return out;
    }
    /* copy into a NUL-terminated local buffer for strtod */
    char buf[64];
    char* p = (self->size < sizeof(buf)) ? buf
            : (char*)z_xmalloc(self->size + 1);
    memcpy(p, self->data, self->size);
    p[self->size] = '\0';
    char* end = NULL;
    errno = 0;
    double v = strtod(p, &end);
    int err = errno;
    uint64_t consumed = (uint64_t)(end - p);
    if (p != buf) free(p);
    if (consumed == 0) {
        out.tag = Z_RESULTVAL_F64_PARSEERROR_TAG_ERR;
        out.data.err = Z_PARSEERROR_TAG_INVALIDDIGIT;
        return out;
    }
    if (consumed != self->size) {
        out.tag = Z_RESULTVAL_F64_PARSEERROR_TAG_ERR;
        out.data.err = Z_PARSEERROR_TAG_INVALIDDIGIT;
        return out;
    }
    if (err == ERANGE) {
        out.tag = Z_RESULTVAL_F64_PARSEERROR_TAG_ERR;
        out.data.err = Z_PARSEERROR_TAG_OVERFLOW;
        return out;
    }
    out.tag = Z_RESULTVAL_F64_PARSEERROR_TAG_OK;
    out.data.ok = v;
    return out;
}


static char* z_sv_to_cstr(z_t85_t v) {
    char* buf = (char*)z_xmalloc(v.size + 1);
    if (v.size > 0) memcpy(buf, v.data, v.size);
    buf[v.size] = '\0';
    return buf;
}

static z_t2366_t z_io_errno_to_IoError(int e) {
    z_t2366_t r = {0};
    r.data = NULL;
    switch (e) {
        case ENOENT:  r.tag = Z_IOERROR_TAG_NOTFOUND; break;
        case EACCES:
        case EPERM:   r.tag = Z_IOERROR_TAG_PERMISSIONDENIED; break;
        case EINTR:   r.tag = Z_IOERROR_TAG_INTERRUPTED; break;
        case EEXIST:  r.tag = Z_IOERROR_TAG_EXISTS; break;
        case EISDIR:  r.tag = Z_IOERROR_TAG_ISDIR; break;
        case ENOTDIR: r.tag = Z_IOERROR_TAG_NOTDIR; break;
        case ENOSPC:  r.tag = Z_IOERROR_TAG_NOSPACE; break;
        default:      r.tag = Z_IOERROR_TAG_OTHER; break;
    }
    return r;
}


/* shared helper: write all bytes; returns 0 ok, errno on failure. */
static int z_io_write_all(int fd, const char* data, uint64_t size) {
    uint64_t off = 0;
    while (off < size) {
        long n = write(fd, data + off, size - off);
        if (n < 0) {
            if (errno == EINTR) continue;
            return errno;
        }
        off += (uint64_t)n;
    }
    return 0;
}

/* shared helper: path + open flags -> write content -> close.
   path and content are borrowed views; caller retains. */
static z_t2425_t z_io_write_common(
    z_t85_t path, z_t85_t content, int flags
) {
    z_t2425_t result = {0};
    char* path_cstr = z_sv_to_cstr(path);
    int fd = open(path_cstr, flags, 0644);
    free(path_cstr);
    if (fd < 0) {
        int e = errno;
        z_t2366_t* boxed = (z_t2366_t*)z_xmalloc(sizeof(z_t2366_t));
        *boxed = z_io_errno_to_IoError(e);
        result.tag = Z_RESULT_NULL_IOERROR_TAG_ERR;
        result.data = boxed;
        return result;
    }
    int werr = z_io_write_all(fd, content.data, content.size);
    close(fd);
    if (werr != 0) {
        z_t2366_t* boxed = (z_t2366_t*)z_xmalloc(sizeof(z_t2366_t));
        *boxed = z_io_errno_to_IoError(werr);
        result.tag = Z_RESULT_NULL_IOERROR_TAG_ERR;
        result.data = boxed;
        return result;
    }
    result.tag = Z_RESULT_NULL_IOERROR_TAG_OK;
    result.data = NULL;
    return result;
}


static z_t2414_t z_io_u64_ok(uint64_t v);
static z_t2414_t z_io_u64_ok(uint64_t v) {
    z_t2414_t result = {0};
    uint64_t* boxed = (uint64_t*)z_xmalloc(sizeof(uint64_t));
    *boxed = v;
    result.tag = Z_RESULT_BOX_U64_IOERROR_TAG_OK;
    result.data = boxed;
    return result;
}

static z_t2414_t z_io_u64_err(int saved_errno);
static z_t2414_t z_io_u64_err(int saved_errno) {
    z_t2414_t result = {0};
    z_t2366_t* boxed = (z_t2366_t*)z_xmalloc(sizeof(z_t2366_t));
    *boxed = z_io_errno_to_IoError(saved_errno);
    result.tag = Z_RESULT_BOX_U64_IOERROR_TAG_ERR;
    result.data = boxed;
    return result;
}


static z_t2425_t z_io_wrap_null_Result(int rc, int saved_errno) {
    z_t2425_t result = {0};
    if (rc == 0) {
        result.tag = Z_RESULT_NULL_IOERROR_TAG_OK;
        result.data = NULL;
        return result;
    }
    z_t2366_t* boxed = (z_t2366_t*)z_xmalloc(sizeof(z_t2366_t));
    *boxed = z_io_errno_to_IoError(saved_errno);
    result.tag = Z_RESULT_NULL_IOERROR_TAG_ERR;
    result.data = boxed;
    return result;
}


/* Populate fs from a struct stat. Shared by z_io_stat / z_io_lstat —
   the only behavioral split between them lives in the syscall call
   site (stat(2) follows symlinks, lstat(2) does not). */
static void z_io_fill_filestat(z_t2584_t* fs, const struct stat* sb);
static void z_io_fill_filestat(z_t2584_t* fs, const struct stat* sb) {
    if (S_ISREG(sb->st_mode))       fs->kind = Z_FILEKIND_TAG_FILE;
    else if (S_ISDIR(sb->st_mode))  fs->kind = Z_FILEKIND_TAG_DIR;
    else if (S_ISLNK(sb->st_mode))  fs->kind = Z_FILEKIND_TAG_SYMLINK;
    else                            fs->kind = Z_FILEKIND_TAG_OTHER;
    fs->size = (uint64_t)sb->st_size;
    fs->mtimeSeconds = (uint64_t)sb->st_mtime;
    fs->atimeSeconds = (uint64_t)sb->st_atime;
    fs->ctimeSeconds = (uint64_t)sb->st_ctime;
    fs->mode = (uint32_t)sb->st_mode;
    fs->device = (uint64_t)sb->st_dev;
    fs->inode = (uint64_t)sb->st_ino;
    fs->nlink = (uint64_t)sb->st_nlink;
}


static void z_io_eprintln(z_t85_t sv) {
    fprintf(stderr, "%.*s\n", (int)sv.size, sv.data);
}


static bool z_io_exists(z_t85_t path) {
    char* path_cstr = z_sv_to_cstr(path);
    int r = access(path_cstr, F_OK);
    free(path_cstr);
    return r == 0;
}


static z_t2368_t z_io_readText(z_t85_t path) {
    /* path is a borrowed view; caller retains ownership */
    z_t2368_t result = {0};
    char* path_cstr = z_sv_to_cstr(path);
    int fd = open(path_cstr, O_RDONLY);
    free(path_cstr);
    if (fd < 0) {
        int e = errno;
        z_t2366_t* boxed = (z_t2366_t*)z_xmalloc(sizeof(z_t2366_t));
        *boxed = z_io_errno_to_IoError(e);
        result.tag = Z_RESULT_STRING_IOERROR_TAG_ERR;
        result.data = boxed;
        return result;
    }
    z_t57_t content = z_t57_create((uint64_t)4096);
    char buf[4096];
    for (;;) {
        long n = read(fd, buf, sizeof(buf));
        if (n == 0) break;
        if (n < 0) {
            if (errno == EINTR) continue;
            int e = errno;
            close(fd);
            z_t57_free(&content);
            z_t2366_t* boxed = (z_t2366_t*)z_xmalloc(sizeof(z_t2366_t));
            *boxed = z_io_errno_to_IoError(e);
            result.tag = Z_RESULT_STRING_IOERROR_TAG_ERR;
            result.data = boxed;
            return result;
        }
        z_t57_append(&content, buf, (uint64_t)n);
    }
    close(fd);
    z_t57_t* boxed = (z_t57_t*)z_xmalloc(sizeof(z_t57_t));
    *boxed = content;
    result.tag = Z_RESULT_STRING_IOERROR_TAG_OK;
    result.data = boxed;
    return result;
}


/* readlink — follow-free read of a symlink's target. readlink(2)
   does not NUL-terminate, and we don't know the exact target size
   up front; loop with a growing buffer until the kernel says the
   full target fit. EINVAL from readlink means the path exists but
   isn't a symbolic link -- surfaced as invalidpath with a
   caller-readable message. The success path breaks out so the body ends
   in its return -- c2mir miscompiles a struct return otherwise. */
static z_t2368_t z_io_readlink(z_t85_t path);
static z_t2368_t z_io_readlink(z_t85_t path) {
    z_t2368_t result = {0};
    char* path_cstr = z_sv_to_cstr(path);
    uint64_t cap = (uint64_t)256;
    char* buf = (char*)z_xmalloc(cap);
    ssize_t n;
    for (;;) {
        n = readlink(path_cstr, buf, cap);
        if (n < 0) {
            int e = errno;
            free(buf);
            free(path_cstr);
            z_t2366_t* boxed = (z_t2366_t*)z_xmalloc(sizeof(z_t2366_t));
            if (e == EINVAL) {
                z_t2366_t v = {0};
                v.tag = Z_IOERROR_TAG_INVALIDPATH;
                z_t57_t* sp = (z_t57_t*)z_xmalloc(sizeof(z_t57_t));
                *sp = z_t57_new("not a symbolic link");
                v.data = sp;
                *boxed = v;
            } else {
                *boxed = z_io_errno_to_IoError(e);
            }
            result.tag = Z_RESULT_STRING_IOERROR_TAG_ERR;
            result.data = boxed;
            return result;
        }
        if ((uint64_t)n < cap) break;
        cap *= 2;
        buf = (char*)z_xrealloc(buf, cap);
    }
    z_t57_t target = {0};
    target.size = (uint64_t)n;
    target.capacity = target.size + 1;
    target.data = (char*)z_xmalloc(target.capacity + 1);
    memcpy(target.data, buf, target.size);
    target.data[target.size] = '\0';
    free(buf);
    free(path_cstr);
    z_t57_t* boxed = (z_t57_t*)z_xmalloc(sizeof(z_t57_t));
    *boxed = target;
    result.tag = Z_RESULT_STRING_IOERROR_TAG_OK;
    result.data = boxed;
    return result;
}


static z_t2425_t z_io_remove(z_t85_t path) {
    char* path_cstr = z_sv_to_cstr(path);
    /* try unlink first; if EISDIR, fall back to rmdir */
    int rc = unlink(path_cstr);
    int e = errno;
    if (rc != 0 && e == EISDIR) {
        rc = rmdir(path_cstr);
        e = errno;
    }
    free(path_cstr);
    return z_io_wrap_null_Result(rc, e);
}


/* stat(2) follows symlinks; the SYMLINK arm never fires here —
   that arm is reached through z_io_lstat. Returns the filestat
   value by value (not boxed); the compiler-generated result
   destructor frees the ok payload's heap copy. */
static z_t2596_t z_io_stat(z_t85_t path);
static z_t2596_t z_io_stat(z_t85_t path) {
    z_t2596_t result = {0};
    char* path_cstr = z_sv_to_cstr(path);
    struct stat sb;
    int rc = stat(path_cstr, &sb);
    int e = errno;
    free(path_cstr);
    if (rc != 0) {
        z_t2366_t* boxed = (z_t2366_t*)z_xmalloc(sizeof(z_t2366_t));
        *boxed = z_io_errno_to_IoError(e);
        result.tag = Z_RESULT_BOX_FILESTAT_IOERROR_TAG_ERR;
        result.data = boxed;
        return result;
    }
    z_t2584_t fs = {0};
    z_io_fill_filestat(&fs, &sb);
    z_t2584_t* boxed = (z_t2584_t*)z_xmalloc(sizeof(z_t2584_t));
    *boxed = fs;
    result.tag = Z_RESULT_BOX_FILESTAT_IOERROR_TAG_OK;
    result.data = boxed;
    return result;
}


static z_t2425_t z_io_writeText(
    z_t85_t path, z_t85_t content
) {
    return z_io_write_common(path, content, O_WRONLY | O_CREAT | O_TRUNC);
}


/* file.close — explicit close that surfaces delayed write errors.
   Marks the file as closed so z_t2376_destroy skips a second close. */
static z_t2425_t z_t2376_close(z_t2376_t* p);
static z_t2425_t z_t2376_close(z_t2376_t* p) {
    z_t2425_t result = {0};
    if (!p || p->closed) {
        result.tag = Z_RESULT_NULL_IOERROR_TAG_OK;
        result.data = NULL;
        return result;
    }
    int rc = close(p->fd);
    int e = errno;
    p->closed = true;
    return z_io_wrap_null_Result(rc, e);
}


/* file.write — write all bytes from `src`. Loops on short writes;
   retries on EINTR. Returns total bytes written on success.
   `src` is a listview (layout: length, data*), matching byteview. */
static z_t2414_t z_t2376_write(
    z_t2376_t* f, z_t2395_t* src
);
static z_t2414_t z_t2376_write(
    z_t2376_t* f, z_t2395_t* src
) {
    uint64_t total = 0;
    while (total < src->length) {
        long n = write(f->fd, src->data + total, src->length - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            return z_io_u64_err(errno);
        }
        total += (uint64_t)n;
    }
    return z_io_u64_ok(total);
}


/* file.read — read up to `max` bytes, appending to `buf`.
   Grows the list capacity as needed. Returns actual bytes read
   (0 indicates EOF); retries on EINTR. The loop breaks out so the body
   ends in its return -- c2mir miscompiles a struct return otherwise. */
static z_t2414_t z_t2376_read(
    z_t2376_t* f, z_t2380_t* buf, uint64_t max
);
static z_t2414_t z_t2376_read(
    z_t2376_t* f, z_t2380_t* buf, uint64_t max
) {
    if (buf->capacity < buf->length + max) {
        uint64_t newcap = buf->length + max;
        buf->data = (uint8_t*)z_xrealloc(buf->data, newcap);
        buf->capacity = newcap;
    }
    long n;
    for (;;) {
        n = read(f->fd, buf->data + buf->length, max);
        if (n >= 0) break;
        if (errno != EINTR) return z_io_u64_err(errno);
    }
    buf->length += (uint64_t)n;
    return z_io_u64_ok((uint64_t)n);
}


/* file.seek — reposition the fd head. Maps seekorigin to the
   matching POSIX whence constant. Returns the new absolute
   position measured from the start of the file. */
static z_t2414_t z_t2376_seek(
    z_t2376_t* f, int64_t off, z_t2436_t origin
);
static z_t2414_t z_t2376_seek(
    z_t2376_t* f, int64_t off, z_t2436_t origin
) {
    int whence;
    switch (origin) {
        case Z_SEEKORIGIN_TAG_START:   whence = SEEK_SET; break;
        case Z_SEEKORIGIN_TAG_CURRENT: whence = SEEK_CUR; break;
        case Z_SEEKORIGIN_TAG_END:     whence = SEEK_END; break;
        default:                       whence = SEEK_SET; break;
    }
    off_t pos = lseek(f->fd, (off_t)off, whence);
    if (pos < 0) return z_io_u64_err(errno);
    return z_io_u64_ok((uint64_t)pos);
}


/* file.flush — no-op for raw file descriptors (POSIX write goes
   directly to the kernel, no userspace buffer to drain). Exists
   so file satisfies the `writer` protocol signature. */
static z_t2425_t z_t2376_flush(z_t2376_t* f);
static z_t2425_t z_t2376_flush(z_t2376_t* f) {
    (void)f;
    z_t2425_t result = {0};
    result.tag = Z_RESULT_NULL_IOERROR_TAG_OK;
    result.data = NULL;
    return result;
}


